def minPointsTwice(intervals):
    ordered = sorted(intervals, key=lambda iv: (iv[1], -iv[0]))
    lo = hi = -10
    count = 0
    for a, b in ordered:
        if a > hi:
            lo, hi = b - 1, b
            count += 2
        elif a > lo:
            lo, hi = hi, b
            count += 1
    return count
